def transform(g):
    n=len(g); c=n//2; m=3; out=[[0]*m for _ in range(m)]
    # corner directions -> corners; edge directions -> diagonal ring-1 cells
    corner={(0,0):(-c,-c),(0,2):(-c,c),(2,0):(c,-c),(2,2):(c,c)}
    edge={(0,1):(-1,-1),(2,1):(1,1),(1,0):(1,-1),(1,2):(-1,1)}
    for i in range(m):
        for j in range(m):
            if (i,j)==(1,1): out[i][j]=g[c][c]
            elif (i,j) in corner:
                dr,dc=corner[(i,j)]; out[i][j]=g[c+dr][c+dc]
            else:
                dr,dc=edge[(i,j)]; out[i][j]=g[c+dr][c+dc]
    return out
